import json
from pathlib import Path
b=Path('/tmp/objective-recovery-runs/u284/packet')
for name in ['screen','qualify']:
 d=json.load(open(b/f'abba-oversubscription/{name}.json')); print('\n'+name)
 for l in d['looks']:
  s=l['selected_resident_service']; print(l['route'], 'svc',s,'busy',l['average_busy_cores'],'cpu',l['aggregate_cpu_seconds'],'life',l['complete_lifecycle_seconds'],'util',l['hardware_utilization_fraction'])
t=json.load(open(b/'c54-trace/timing-trace.json'))
from collections import defaultdict
agg=defaultdict(lambda:[0,0,0])
for e in t['events']:
 if e['kind']=='phase':
  p=e['phase']; agg[p][0]+=e['end_ns']-e['start_ns']; agg[p][1]+=e.get('thread_cpu_ns') or 0; agg[p][2]+=1
print('\ntrace phase inclusive duration/cpu seconds/event count')
for k,v in sorted(agg.items(), key=lambda kv:-kv[1][0]): print(k, round(v[0]/1e9,3),round(v[1]/1e9,3),v[2])
